begin;

delete from public.version_banners vb
using public.game_versions gv, public.games g
where vb.version_id=gv.id and gv.game_id=g.id and g.code='YYS'
  and gv.version_no between 'YYS-2024-01-01' and 'YYS-2026-07-31';

with yys as (select id from public.games where code='YYS' limit 1),payload as (select $json$[{"version_no":"YYS-2024-01-10","version_name":"黄金夜航","start_date":"2024-01-10","note":"客户端版本：1.8.2。","banners":[{"character":"泷","banner_type":"pickup"}]},{"version_no":"YYS-2024-02-07","version_name":"鲸汐永歌","start_date":"2024-02-07","note":"客户端版本：1.8.4。","banners":[{"character":"鲸汐千姬","banner_type":"pickup"},{"character":"福悦座敷童子","banner_type":"pickup"}]},{"version_no":"YYS-2024-03-06","version_name":"聚光之音","start_date":"2024-03-06","note":"客户端版本：1.8.4。初音未来联动。","banners":[{"character":"初音未来","banner_type":"collab"},{"character":"镜音铃·连","banner_type":"collab"}]},{"version_no":"YYS-2024-04-03","version_name":"福神巡游","start_date":"2024-04-03","note":"客户端版本：1.8.9。","banners":[{"character":"晨晖惠比寿","banner_type":"pickup"}]},{"version_no":"YYS-2024-04-24","version_name":"神隐寻真","start_date":"2024-04-24","note":"客户端版本：1.8.11。《雾山五行》联动后续角色。","banners":[{"character":"申屠子夜","banner_type":"collab"}]},{"version_no":"YYS-2024-05-22","version_name":"蜃楼之变","start_date":"2024-05-22","note":"客户端版本：1.8.12。","banners":[{"character":"龙吟铃鹿御前","banner_type":"pickup"}]},{"version_no":"YYS-2024-06-19","version_name":"泉涌财盈","start_date":"2024-06-19","note":"客户端版本：1.8.12。","banners":[{"character":"猫川","banner_type":"pickup"}]},{"version_no":"YYS-2024-07-17","version_name":"祸神盛宴","start_date":"2024-07-17","note":"客户端版本：1.8.16。","banners":[{"character":"祸津神","banner_type":"pickup"}]},{"version_no":"YYS-2024-08-14","version_name":"花火之约","start_date":"2024-08-14","note":"客户端版本：1.8.18。","banners":[{"character":"遥念烟烟罗","banner_type":"pickup"}]},{"version_no":"YYS-2024-09-11","version_name":"八周年·云华之卷","start_date":"2024-09-11","note":"客户端版本：1.8.19。国服八周年大型版本。","banners":[{"character":"龙珏","banner_type":"pickup"},{"character":"心友犬神","banner_type":"pickup"}]},{"version_no":"YYS-2024-10-09","version_name":"踏雪寻踪","start_date":"2024-10-09","note":"客户端版本：1.8.20。","banners":[{"character":"封阳君","banner_type":"pickup"}]},{"version_no":"YYS-2024-11-06","version_name":"千面摘星","start_date":"2024-11-06","note":"客户端版本：1.8.21。","banners":[{"character":"鬼金羊","banner_type":"pickup"}]},{"version_no":"YYS-2024-12-04","version_name":"神醉绮宴","start_date":"2024-12-04","note":"客户端版本：1.8.26。","banners":[{"character":"神酿星熊童子","banner_type":"pickup"}]},{"version_no":"YYS-2024-12-31","version_name":"友人偕行","start_date":"2024-12-31","note":"《夏目友人帐》联动。","banners":[{"character":"夏目&猫老师","banner_type":"collab"}]},{"version_no":"YYS-2025-02-26","version_name":"花间歌弈","start_date":"2025-02-26","note":"客户端版本：1.8.31。","banners":[{"character":"歌留多","banner_type":"pickup"}]},{"version_no":"YYS-2025-03-26","version_name":"巡梦之音","start_date":"2025-03-26","note":"客户端版本：1.8.34。VOCALOID联动后续。","banners":[{"character":"巡音流歌","banner_type":"collab"},{"character":"初音未来","banner_type":"rerun"},{"character":"镜音铃·连","banner_type":"rerun"}]},{"version_no":"YYS-2025-04-23","version_name":"日轮之城·日耀将升","start_date":"2025-04-23","note":"客户端版本：1.8.35。日轮之城/邪马台篇大型版本。","banners":[{"character":"卑弥呼","banner_type":"pickup"}]},{"version_no":"YYS-2025-05-21","version_name":"月曜永恒","start_date":"2025-05-21","note":"客户端版本：1.8.36。","banners":[{"character":"时曜泷夜叉姬","banner_type":"pickup"}]},{"version_no":"YYS-2025-06-18","version_name":"火照归途","start_date":"2025-06-18","note":"客户端版本：1.8.37。","banners":[{"character":"荒骷髅","banner_type":"pickup"}]},{"version_no":"YYS-2025-07-16","version_name":"云深不见","start_date":"2025-07-16","note":"客户端版本：1.8.39。","banners":[{"character":"云间不见岳","banner_type":"pickup"}]},{"version_no":"YYS-2025-07-23","version_name":"历史更新｜湍津姬登场","start_date":"2025-07-23","note":"客户端版本：1.8.39。GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"湍津姬","banner_type":"standard_addition"}]},{"version_no":"YYS-2025-08-13","version_name":"樱梦游园","start_date":"2025-08-13","note":"客户端版本：1.8.41。《魔卡少女樱》联动。","banners":[{"character":"木之本樱","banner_type":"collab"},{"character":"李小狼","banner_type":"collab"}]},{"version_no":"YYS-2025-09-10","version_name":"九周年·冰火永烬","start_date":"2025-09-10","note":"国服九周年大型版本。","banners":[{"character":"雪御前","banner_type":"pickup"},{"character":"妙主九命猫","banner_type":"pickup"}]},{"version_no":"YYS-2025-10-10","version_name":"狩日之决","start_date":"2025-10-10","note":"客户端版本：1.8.45。九周年庆·下篇。","banners":[{"character":"平将门","banner_type":"pickup"}]},{"version_no":"YYS-2025-10-29","version_name":"绯夜猎影","start_date":"2025-10-29","note":"客户端版本：1.8.47。","banners":[{"character":"妖刀姬·绯夜猎刃","banner_type":"pickup"}]},{"version_no":"YYS-2025-11-19","version_name":"入梦偕行","start_date":"2025-11-19","note":"客户端版本：1.8.49。","banners":[{"character":"梦引蝴蝶精","banner_type":"pickup"}]},{"version_no":"YYS-2025-12-17","version_name":"梦山新话","start_date":"2025-12-17","note":"客户端版本：1.8.51。","banners":[{"character":"梦山白藏主","banner_type":"pickup"}]},{"version_no":"YYS-2026-01-14","version_name":"月自长梦升","start_date":"2026-01-14","note":"客户端版本：1.8.52。","banners":[{"character":"神无月","banner_type":"pickup"}]},{"version_no":"YYS-2026-02-11","version_name":"归狐谣","start_date":"2026-02-11","note":"客户端版本：1.8.53。","banners":[{"character":"葛叶","banner_type":"pickup"},{"character":"灼华桃花妖","banner_type":"pickup"}]},{"version_no":"YYS-2026-03-11","version_name":"诡夜百戏","start_date":"2026-03-11","note":"客户端版本：1.8.56。","banners":[{"character":"蚀月吸血姬","banner_type":"pickup"}]},{"version_no":"YYS-2026-04-01","version_name":"雪山之章·夜见前事","start_date":"2026-04-01","note":"客户端版本：1.8.58。","banners":[{"character":"市加美","banner_type":"pickup"}]},{"version_no":"YYS-2026-04-29","version_name":"雪山之章·醒世达观","start_date":"2026-04-29","note":"客户端版本：1.8.62。","banners":[{"character":"思金神","banner_type":"pickup"}]},{"version_no":"YYS-2026-05-27","version_name":"雪山之章·执火燎原","start_date":"2026-05-27","note":"客户端版本：1.8.63。","banners":[{"character":"天火命铃彦姬","banner_type":"pickup"}]},{"version_no":"YYS-2026-06-24","version_name":"金砂福威","start_date":"2026-06-24","note":"客户端版本：1.8.66。","banners":[{"character":"毗沙门天","banner_type":"pickup"}]},{"version_no":"YYS-2026-07-22","version_name":"洪狐天运","start_date":"2026-07-22","note":"客户端版本：2.8.76。","banners":[{"character":"不相狐禅","banner_type":"pickup"}]}]$json$::jsonb data),
vr as(select x from payload cross join lateral jsonb_array_elements(data)x),
upserted as (
 insert into public.game_versions(game_id,version_no,version_name,start_date,note)
 select yys.id,x->>'version_no',x->>'version_name',(x->>'start_date')::date,nullif(x->>'note','') from yys cross join vr
 on conflict(game_id,version_no) do update set version_name=excluded.version_name,start_date=excluded.start_date,note=excluded.note,updated_at=now()
 returning id,version_no
),
br as(select x->>'version_no' version_no,b from vr cross join lateral jsonb_array_elements(coalesce(x->'banners','[]'::jsonb))b)
insert into public.version_banners(version_id,phase,banner_type,character_id,character_name_raw)
select u.id,case when br.b->>'banner_type'='standard_addition' then 'standard' else 'other' end,br.b->>'banner_type',c.id,br.b->>'character'
from br join upserted u using(version_no)
left join public.characters c on c.game_id=(select id from yys) and c.name=br.b->>'character';

insert into public.resources(id,resource_type,title,url,note,source,source_host,source_authority,ingested_via)
values(gen_random_uuid(),'game_phase_reference','《阴阳师》官服历史更新日志（历史版本交叉核对）','https://m.3839.com/gamehistorylog/76473.htm','用于交叉核对国服历史客户端更新日期、近年版本主题、新式神与活动；属于第三方历史汇总，不替代网易官方公告。','3839游戏历史日志','m.3839.com','community','migration')
on conflict(url) where url is not null do update set title=excluded.title,note=excluded.note,source=excluded.source,source_host=excluded.source_host,source_authority=excluded.source_authority,updated_at=now();

with yys as (select id from public.games where code='YYS' limit 1),r as (select id from public.resources where url='https://m.3839.com/gamehistorylog/76473.htm')
insert into public.resource_relations(id,resource_id,entity_type,entity_id,relation_type)
select gen_random_uuid(),r.id,'game',yys.id,'reference' from yys cross join r
where not exists(select 1 from public.resource_relations rr where rr.resource_id=r.id and rr.entity_type='game' and rr.entity_id=yys.id and rr.relation_type='reference');

with yys as (select id from public.games where code='YYS' limit 1),r as (select id from public.resources where url='https://m.3839.com/gamehistorylog/76473.htm')
insert into public.resource_relations(id,resource_id,entity_type,entity_id,relation_type)
select gen_random_uuid(),r.id,'version',gv.id,'reference' from public.game_versions gv join yys on yys.id=gv.game_id cross join r
where gv.version_no like 'YYS-%'
  and not exists(select 1 from public.resource_relations rr where rr.resource_id=r.id and rr.entity_type='version' and rr.entity_id=gv.id and rr.relation_type='reference');

commit;
